// ─── AUTO-INDEXER: maps catalog mechanism codes → bridge keys ───
export const CATALOG_MECH_TO_BRIDGE: Record<string, string[]> = {};
(function buildReverseIndex() {
  for (const [bridgeKey, catalogCodes] of Object.entries(BRIDGE_MECH_TO_CATALOG)) {
    for (const code of catalogCodes) {
      if (!CATALOG_MECH_TO_BRIDGE[code]) CATALOG_MECH_TO_BRIDGE[code] = [];
      if (!CATALOG_MECH_TO_BRIDGE[code].includes(bridgeKey)) CATALOG_MECH_TO_BRIDGE[code].push(bridgeKey);
    }
  }
})();

// ─── Find all catalog substances covering a bridge mechanism ───
import { SUPPORT_CATALOG_DATA } from './support-catalog-data';

export function findCatalogSubstancesForBridgeMech(bridgeKey: string): string[] {
  const catalogCodes = BRIDGE_MECH_TO_CATALOG[bridgeKey] || [];
  if (catalogCodes.length === 0) return [];
  const found = new Set<string>();
  for (const [subId, entry] of Object.entries(SUPPORT_CATALOG_DATA)) {
    const mechs = entry.mechanisms || [];
    for (const code of catalogCodes) {
      if (mechs.includes(code)) { found.add(subId); break; }
    }
  }
  return [...found];
}

// ─── Find bridge mechanisms covered by a substance ───
export function findBridgeMechsForSubstance(substanceId: string): string[] {
  const entry = SUPPORT_CATALOG_DATA[substanceId];
  if (!entry) {
    const upper = substanceId.toUpperCase();
    const e2 = SUPPORT_CATALOG_DATA[upper];
    if (!e2) return [];
    return findBridgeMechsForSubstance(upper);
  }
  const mechs = entry.mechanisms || [];
  const bridgeKeys = new Set<string>();
  for (const code of mechs) {
    const keys = CATALOG_MECH_TO_BRIDGE[code] || [];
    keys.forEach(k => bridgeKeys.add(k));
  }
  return [...bridgeKeys];
}

// ─── Count how many bridge mechanisms a substance covers ───
export function countCoveredMechanisms(substanceId: string): number {
  return findBridgeMechsForSubstance(substanceId).length;
}

// ─── STACK → BRIDGE MECHANISM mapping ───
// Uses stack.mechanismCodes[] → CATALOG_MECH_TO_BRIDGE → bridge keys
export function findBridgeMechsForStack(mechanismCodes: string[]): string[] {
  const bridgeKeys = new Set<string>();
  for (const code of mechanismCodes) {
    const keys = CATALOG_MECH_TO_BRIDGE[code] || [];
    keys.forEach(k => bridgeKeys.add(k));
  }
  return [...bridgeKeys];
}

// ─── Get system coverage for a stack ───
export function getStackSystemCoverage(mechanismCodes: string[]): Record<string, string[]> {
  const bridgeKeys = findBridgeMechsForStack(mechanismCodes);
  const bySystem: Record<string, string[]> = {};
  for (const key of bridgeKeys) {
    const sys = key.split('_')[0];
    if (!bySystem[sys]) bySystem[sys] = [];
    bySystem[sys].push(key);
  }
  return bySystem;
}
